(R/'index.html').write_text('''<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeepInfer · 新旧对比</title><link rel="stylesheet" href="/app.css"><body><header><h1>同一句话，两版表达</h1><p>DeepInfer · 原声原速 · 94.23 秒</p></header><main><section class="pair"><article><h2>之前发布</h2><video id="old" playsinline muted preload="auto"></video></article><article><h2>Fred 重制</h2><video id="new" playsinline preload="auto"></video></article></section><section class="controls"><div class="transport"><button id="play" disabled>播放</button><button id="back">−1 帧</button><button id="forward">+1 帧</button><select id="rate" aria-label="播放速度"><option value="1">1× 原速</option><option value="0.5">0.5×</option></select><button id="sound">声音：新版</button><output id="clock">0:00.000</output></div><input id="seek" type="range" min="0" max="94.216667" step="0.016666667" value="0" aria-label="同步时间轴"><nav id="chapters" aria-label="关键段"></nav><p id="status" role="status">正在载入两版视频…</p><details><summary>版本与检查范围</summary><p>两版共用原声时钟；播放仅新版出声。可同步跳转、半速或逐帧对照。画面已做分时采样检查；连续视听、直接听音及05独立质检仍待完成。</p><div id="versions"></div></details></section></main><script src="/app.js"></script></body></html>''')
(R/'app.css').write_text('''*{box-sizing:border-box}body{margin:0;background:#f5f4f8;color:#17151c;font:15px system-ui,-apple-system,sans-serif}header,main{width:min(100% - 32px,1080px);margin:auto}header{padding:22px 0 12px;display:flex;align-items:baseline;justify-content:space-between;gap:20px}h1{font-size:25px;margin:0}header p{color:#666;margin:0}.pair{display:flex;justify-content:center;gap:24px}article{min-width:0;width:min(42vw,calc((100vh - 275px)*.5625));text-align:center}h2{font-size:16px;font-weight:600;margin:0 0 8px}video{width:100%;aspect-ratio:9/16;display:block;background:#fff;box-shadow:0 8px 28px #231b3014}.controls{max-width:850px;margin:18px auto}.transport{display:flex;gap:8px;align-items:center;flex-wrap:wrap}button,select{font:inherit;padding:9px 14px;border:0;border-radius:8px;background:#e7e3ed;color:#302739;cursor:pointer}button:hover{background:#dcd4e8}#play{background:#6942c4;color:white;min-width:72px}button:disabled{opacity:.5;cursor:wait}output{font-variant-numeric:tabular-nums;margin-left:auto}#seek{width:100%;accent-color:#6942c4;margin:16px 0}nav{display:flex;gap:7px;flex-wrap:wrap}nav button{font-size:13px;padding:7px 10px}#status{color:#6e637c;font-size:13px;margin:12px 0}details{font-size:13px;line-height:1.5;color:#62596d}#versions{overflow-wrap:anywhere}#versions p{margin:8px 0}@media(max-width:650px){header{display:block}header p{margin-top:6px;font-size:13px}h1{font-size:21px}.pair{gap:10px}article{width:calc(50% - 5px)}.transport{gap:6px}button,select{padding:8px;font-size:13px}output{font-size:12px}.controls{margin-top:15px}}''')
(R/'app.js').write_text('''const oldVideo=document.getElementById('old'), newVideo=document.getElementById('new'), play=document.getElementById('play'), seek=document.getElementById('seek'), status=document.getElementById('status'), clock=document.getElementById('clock');
oldVideo.muted=true;let running=false,muted=false,seeking=false,raf=0;
const format=t=>`${Math.floor(t/60)}:${(t%60).toFixed(3).padStart(6,'0')}`;
function display(){clock.value=format(newVideo.currentTime);if(!seeking)seek.value=newVideo.currentTime;}
function pause(){running=false;newVideo.pause();oldVideo.pause();play.textContent='播放';cancelAnimationFrame(raf);display();}
function syncLoop(){if(!running)return;const drift=oldVideo.currentTime-newVideo.currentTime;if(Math.abs(drift)>.055){oldVideo.currentTime=newVideo.currentTime;oldVideo.playbackRate=newVideo.playbackRate;}else oldVideo.playbackRate=Math.max(.1,newVideo.playbackRate-drift*.6);display();raf=requestAnimationFrame(syncLoop);}
async function start(){if(newVideo.currentTime>=94.2)jump(0);oldVideo.currentTime=newVideo.currentTime;oldVideo.playbackRate=newVideo.playbackRate;try{await Promise.all([newVideo.play(),oldVideo.play()]);running=true;play.textContent='暂停';status.textContent='同步播放 · 仅新版声音';syncLoop();}catch(e){pause();status.textContent='播放未启动，请再点击播放。';}}
function jump(t){pause();t=Math.max(0,Math.min(5653/60,t));newVideo.currentTime=t;oldVideo.currentTime=t;display();status.textContent='已同步定位 · '+format(t);}
play.onclick=()=>running?pause():start();document.getElementById('back').onclick=()=>jump((Math.round(newVideo.currentTime*60)-1)/60);document.getElementById('forward').onclick=()=>jump((Math.round(newVideo.currentTime*60)+1)/60);
seek.oninput=()=>{seeking=true;jump(Number(seek.value));seeking=false};document.getElementById('rate').onchange=e=>{newVideo.playbackRate=Number(e.target.value);oldVideo.playbackRate=newVideo.playbackRate};document.getElementById('sound').onclick=e=>{muted=!muted;newVideo.muted=muted;oldVideo.muted=true;e.target.textContent=muted?'声音：静音':'声音：新版'};
newVideo.onended=pause;newVideo.onseeked=display;document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
fetch('/catalog.json').then(r=>r.json()).then(async c=>{oldVideo.src=c.versions[0].url;newVideo.src=c.versions[1].url;for(const s of c.chapters){const b=document.createElement('button');b.textContent=s.label;b.onclick=()=>jump(s.time);document.getElementById('chapters').append(b)}for(const v of c.versions){const p=document.createElement('p');p.textContent=v.label+' · '+v.filename+' · SHA256 '+v.sha256;document.getElementById('versions').append(p)}await Promise.all([oldVideo,newVideo].map(v=>new Promise((resolve,reject)=>{if(v.readyState>=1)resolve();else{v.addEventListener('loadedmetadata',resolve,{once:true});v.addEventListener('error',reject,{once:true})}})));play.disabled=false;status.textContent='两版已就绪 · 同步定位 · 仅新版出声';}).catch(()=>{status.textContent='文件载入失败，请检查本地预览服务。'});
''')
